'use strict';

// The VAPID application server key (RFC 8292, advertised per RFC 9749). One P-256 key pair for the
// whole installation, generated by the first worker that starts and kept in the settings collection
// (not enumerable, so the settings listing does not show it). Every worker reads it at start and again
// at a fixed interval, so a rotation reaches all of them.
//
// Rotation: remove the setting (`db.settings.deleteOne({key: 'jmap:vapid'})`). The next worker that
// reads it generates a new key pair, the session state changes, and subscriptions created under the old
// key are destroyed when their next push is due (RFC 9749 5, no transition period).

const crypto = require('crypto');
const log = require('npmlog');
const { b64url } = require('./webpush');

const SETTING = 'jmap:vapid';

/** A new key pair in its stored form */
function generate() {
    const { privateKey, publicKey } = crypto.generateKeyPairSync('ec', { namedCurve: 'prime256v1' });
    const jwk = publicKey.export({ format: 'jwk' });
    const raw = Buffer.concat([Buffer.from([4]), Buffer.from(jwk.x, 'base64url'), Buffer.from(jwk.y, 'base64url')]);
    return {
        publicKey: b64url(raw),
        privateKey: privateKey.export({ format: 'pem', type: 'pkcs8' }).toString(),
        created: new Date().toISOString()
    };
}

/** The usable form of a stored key pair: {id, publicKey (base64url), privateKey (KeyObject)} */
function load(stored) {
    return {
        // short, stable name of the key, stored on every subscription created under it
        id: crypto.createHash('sha256').update(stored.publicKey).digest('base64url').slice(0, 16),
        publicKey: stored.publicKey,
        privateKey: crypto.createPrivateKey(stored.privateKey)
    };
}

class VapidKeys {
    /**
     * @param {Db} database the database with the settings collection
     * @param {Object} [options] {refresh: seconds between two reads of the setting}
     */
    constructor(database, options = {}) {
        this.database = database;
        this.refreshInterval = options.refresh || 60;
        this.current = null;
        this.timer = null;
    }

    /** Reads the key pair, creating it when there is none */
    async read() {
        const settings = this.database.collection('settings');
        let row = await settings.findOne({ key: SETTING }, { projection: { value: true } });
        if (!row) {
            try {
                row = await settings.findOneAndUpdate(
                    { key: SETTING },
                    { $setOnInsert: { key: SETTING, value: JSON.stringify(generate()), enumerable: false, encrypted: false, created: new Date() } },
                    { upsert: true, returnDocument: 'after', projection: { value: true } }
                );
            } catch (err) {
                // another worker created it at the same time
                if (err.code !== 11000) {
                    throw err;
                }
                row = await settings.findOne({ key: SETTING }, { projection: { value: true } });
            }
        }
        const stored = typeof row.value === 'string' ? JSON.parse(row.value) : row.value;
        if (!this.current || this.current.publicKey !== stored.publicKey) {
            this.current = load(stored);
        }
        return this.current;
    }

    /** Reads the key once and then at the refresh interval */
    async start() {
        await this.read();
        const tick = () => {
            this.read()
                .catch(err => log.error('JMAP', 'could not read the VAPID key: %s', err.message))
                .finally(() => {
                    if (this.timer) {
                        this.timer = setTimeout(tick, this.refreshInterval * 1000);
                        this.timer.unref();
                    }
                });
        };
        this.timer = setTimeout(tick, this.refreshInterval * 1000);
        this.timer.unref();
        return this;
    }

    stop() {
        clearTimeout(this.timer);
        this.timer = null;
    }
}

module.exports = { VapidKeys, SETTING, generate, load };
